def _load_dotenv_disabled() -> bool:
    """
    Determine if dotenv loading has been disabled.
    """
    if "PYTHON_DOTENV_DISABLED" not in os.environ:
        return False
    value = os.environ["PYTHON_DOTENV_DISABLED"].casefold()
    return value in {"1", "true", "t", "yes", "y"}

@contextmanager
def _get_stream(self) -> Iterator[IO[str]]:
    if self.dotenv_path and _is_file_or_fifo(self.dotenv_path):
        with open(self.dotenv_path, encoding=self.encoding) as stream:
            yield stream
    elif self.stream is not None:
        yield self.stream
    else:
        if self.verbose:
            logger.info(
                "python-dotenv could not find configuration file %s.",
                self.dotenv_path or ".env",
            )
        yield io.StringIO("")

if dotenv_path is None and stream is None:
    dotenv_path = find_dotenv()

return DotEnv(
    dotenv_path=dotenv_path,
    stream=stream,
    verbose=verbose,
    interpolate=interpolate,
    override=True,
    encoding=encoding,
).dict()

def set_as_environment_variables(self) -> bool:
    """
    Load the current dotenv as system environment variable.
    """
    if not self.dict():
        return False

    for k, v in self.dict().items():
        if k in os.environ and not self.override:
            continue
        if v is not None:
            os.environ[k] = v

    return True

def resolve_variables(
    values: Iterable[Tuple[str, Optional[str]]],
    override: bool,
) -> Mapping[str, Optional[str]]:
    new_values: Dict[str, Optional[str]] = {}

    for name, value in values:
        if value is None:
            result = None
        else:
            atoms = parse_variables(value)
            env: Dict[str, Optional[str]] = {}
            if override:
                env.update(os.environ)  # type: ignore
                env.update(new_values)
            else:
                env.update(new_values)
                env.update(os.environ)  # type: ignore
            result = "".join(atom.resolve(env) for atom in atoms)

        new_values[name] = result

    return new_values

def __setitem__(self, key, value):
    maxsize = self.__maxsize
    size = self.getsizeof(value)
    if size < 0:
        raise ValueError("value size must be non-negative")
    if size > maxsize:
        raise ValueError("value too large")
    if key not in self.__data:
        diffsize = size
        while self.__currsize + diffsize > maxsize:
            self.popitem()
    else:
        diffsize = size - self.__size[key]
        while self.__currsize + diffsize > maxsize:
            self.popitem()
            if key not in self.__data:
                diffsize = size
    self.__data[key] = value
    self.__size[key] = size
    self.__currsize += diffsize

def pop(self, key, default=__marker):
    if key in self:
        value = self[key]
        del self[key]
    elif default is self.__marker:
        raise KeyError(key)
    else:
        value = default
    return value

def hashkey(*args, **kwargs):
    """Return a cache key for the specified hashable arguments."""

    if kwargs:
        return _HashedTuple(args + _kwmark + tuple(sorted(kwargs.items())))
    else:
        return _HashedTuple(args)


def methodkey(self, *args, **kwargs):
    """Return a cache key for use with cached methods."""
    return hashkey(*args, **kwargs)

def __touch(self, key):
    """Mark as recently used"""
    try:
        self.__order.move_to_end(key)
    except KeyError:
        self.__order[key] = None

def __contains__(self, key):
    try:
        link = self.__links[key]  # no reordering
    except KeyError:
        return False
    else:
        return self.timer() < link.expires

/**
 * Detect Electron renderer / nwjs process, which is node, but we should
 * treat as a browser.
 */

if (typeof process === 'undefined' || process.type === 'renderer' || process.browser === true || process.__nwjs) {
	module.exports = require('./browser.js');
} else {
	module.exports = require('./node.js');
}

function debug(...args) {
	// Disabled?
	if (!debug.enabled) {
		return;
	}

	const self = debug;

	// Set `diff` timestamp
	const curr = Number(new Date());
	const ms = curr - (prevTime || curr);
	self.diff = ms;
	self.prev = prevTime;
	self.curr = curr;
	prevTime = curr;

function coerce(val) {
	if (val instanceof Error) {
		return val.stack || val.message;
	}
	return val;
}

function enable(namespaces) {
	createDebug.save(namespaces);
	createDebug.namespaces = namespaces;

	createDebug.names = [];
	createDebug.skips = [];

	const split = (typeof namespaces === 'string' ? namespaces : '')
		.trim()
		.replace(/\s+/g, ',')
		.split(',')
		.filter(Boolean);

	for (const ns of split) {
		if (ns[0] === '-') {
			createDebug.skips.push(ns.slice(1));
		} else {
			createDebug.names.push(ns);
		}
	}
}

function enabled(name) {
	for (const skip of createDebug.skips) {
		if (matchesTemplate(name, skip)) {
			return false;
		}
	}

	for (const ns of createDebug.names) {
		if (matchesTemplate(name, ns)) {
			return true;
		}
	}

	return false;
}

function extend(namespace, delimiter) {
	const newDebug = createDebug(this.namespace + (typeof delimiter === 'undefined' ? ':' : delimiter) + namespace);
	newDebug.log = this.log;
	return newDebug;
}

const assertValidLevel = level => {
	if (!Number.isSafeInteger(level) || level < 0 || level > 3) {
		throw new Error('The `level` should be an integer from 0 to 3');
	}
};

const applyOptions = (object, options = {}) => {
	if (options.level !== undefined) {
		assertValidLevel(options.level);
	}

	// Detect level if not set manually. Written under the symbol rather than through `level`, as the prototype carrying that accessor is not installed until after this runs.
	const colorLevel = stdoutColor ? stdoutColor.level : 0;
	object[LEVEL] = options.level === undefined ? colorLevel : options.level;
};

const createBuilder = (self, _styler, _isEmpty) => {
	// Single argument is hot path, implicit coercion is faster than anything
	const builder = (...arguments_) => {
		if (arguments_.length === 1) {
			// eslint-disable-next-line no-implicit-coercion
			return applyStyle(builder, '' + arguments_[0]);
		}

		if (arguments_.length === 2) {
			// The template literal matches `Array#join` coercion (`null` and `undefined` become empty, objects use `toString`) while being faster.
			return applyStyle(builder, `${arguments_[0] ?? ''} ${arguments_[1] ?? ''}`);
		}

		return applyStyle(builder, arguments_.join(' '));

// Note: Each match is kept and `postfix` is inserted after it. `String#replaceAll(substring, substring + postfix)` does the same, but it has to scan the replacement for `$` patterns and it is several times slower on the no-match path that most calls take.
export function stringReplaceAll(string, substring, postfix) {
	let index = string.indexOf(substring);
	if (index === -1) {
		return string;
	}

	const substringLength = substring.length;
	let endIndex = 0;
	let returnValue = '';
	do {
		returnValue += string.slice(endIndex, index) + substring + postfix;
		endIndex = index + substringLength;
		index = string.indexOf(substring, endIndex);
	} while (index !== -1);

	returnValue += string.slice(endIndex);
	return returnValue;
}

const applyStyle = (self, string) => {
	// Read the level directly off the generator to skip the `level` getter dispatch on this hot path
	if (self[GENERATOR][LEVEL] <= 0 || !string) {
		// eslint-disable-next-line unicorn/no-computed-property-existence-check -- Reads the boolean value, not a property existence check.
		return self[IS_EMPTY] ? '' : string;
	}

	let styler = self[STYLER];

	if (styler === undefined) {
		return string;
	}

constructor(flags, description) {
  this.flags = flags;
  this.description = description || '';

  this.required = flags.includes('<'); // A value must be supplied when the option is specified.
  this.optional = flags.includes('['); // A value is optional when the option is specified.
  // variadic test ignores <value,...> et al which might be used to describe custom splitting of single argument
  this.variadic = /\w\.\.\.[>\]]$/.test(flags); // The option can take multiple values.
  this.mandatory = false; // The option must have a value after parsing, which usually means it must be specified on command line.
  const optionFlags = splitOptionFlags(flags);
  this.short = optionFlags.shortFlag; // May be a short flag, undefined, or even a long flag (if option has two long flags).
  this.long = optionFlags.longFlag;
  this.negate = false;
  if (this.long) {
    this.negate = this.long.startsWith('--no-');
  }
  this.defaultValue = undefined;
  this.defaultValueDescription = undefined;
  this.presetArg = undefined;
  this.envVar = undefined;
  this.parseArg = undefined;
  this.hidden = false;
  this.argChoices = undefined;
  this.conflictsWith = [];
  this.implied = undefined;
  this.helpGroupHeading = undefined; // soft initialised when option added to command

conflicts(names) {
  this.conflictsWith = this.conflictsWith.concat(names);
  return this;
}

implies(impliedOptionValues) {
  let newImplied = impliedOptionValues;
  if (typeof impliedOptionValues === 'string') {
    // string is not documented, but easy mistake and we can do what user probably intended.
    newImplied = { [impliedOptionValues]: true };
  }
  this.implied = Object.assign(this.implied || {}, newImplied);
  return this;
}

constructor(name, description) {
  this.description = description || '';
  this.variadic = false;
  this.parseArg = undefined;
  this.defaultValue = undefined;
  this.defaultValueDescription = undefined;
  this.argChoices = undefined;

  switch (name[0]) {
    case '<': // e.g. <required>
      this.required = true;
      this._name = name.slice(1, -1);
      break;
    case '[': // e.g. [optional]
      this.required = false;
      this._name = name.slice(1, -1);
      break;
    default:
      this.required = true;
      this._name = name;
      break;
  }

  if (this._name.endsWith('...')) {
    this.variadic = true;
    this._name = this._name.slice(0, -3);
  }
}

name() {
  return this._name;
}

_collectValue(value, previous) {
  if (previous === this.defaultValue || !Array.isArray(previous)) {
    return [value];
  }

  previous.push(value);
  return previous;
}

choices(values) {
  this.argChoices = values.slice();
  this.parseArg = (arg, previous) => {
    if (!this.argChoices.includes(arg)) {
      throw new InvalidArgumentError(
        `Allowed choices are ${this.argChoices.join(', ')}.`,
      );
    }
    if (this.variadic) {
      return this._collectValue(arg, previous);
    }
    return arg;
  };
  return this;
}

